const int LED = 13;
const int CAPTEUR = A0;
const int SEUIL = 512;

void setup() {
  pinMode(LED, OUTPUT);
}

void loop() {
  int val = analogRead(CAPTEUR);
  if (val > SEUIL) {
    digitalWrite(LED, HIGH);
  } else {
    digitalWrite(LED, LOW);
  }
  delay(100);
}

